-- ==============================================================================
-- WORDLE GAME SCHEMA MIGRATION (PostgreSQL / Supabase)
-- ==============================================================================

-- 1. Table: wordle_words
-- Stores the 5-letter daily words generated by the backend.
CREATE TABLE IF NOT EXISTS public.wordle_words (
    id VARCHAR(64) PRIMARY KEY,
    word VARCHAR(10) NOT NULL,
    creation_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for fast lookup by creation date
CREATE INDEX IF NOT EXISTS idx_wordle_words_creation_date ON public.wordle_words(creation_date DESC);

-- 2. Table: wordle_solves
-- Stores daily leaderboard submissions for users who solved today's Wordle.
CREATE TABLE IF NOT EXISTS public.wordle_solves (
    id VARCHAR(64) PRIMARY KEY,
    word_id VARCHAR(64) NOT NULL,
    date DATE NOT NULL DEFAULT CURRENT_DATE,
    user_id VARCHAR(64),
    user_name VARCHAR(255) NOT NULL,
    user_avatar TEXT,
    guesses JSONB NOT NULL DEFAULT '[]'::jsonb,
    grid_pattern JSONB NOT NULL DEFAULT '[]'::jsonb,
    attempts INT NOT NULL,
    solved_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_wordle_solves_date ON public.wordle_solves(date DESC);
CREATE INDEX IF NOT EXISTS idx_wordle_solves_word_id ON public.wordle_solves(word_id);
